// Serves every page. Only the login page is public; all other pages need a valid session.
// The pages themselves live in _pages.js (generated by build.js), so they are never exposed as static files.
const pages = require("./_pages.js");
const { getSession, redirect } = require("./_auth.js");

module.exports = (req, res) => {
  const p = new URL(req.url, "http://localhost").searchParams.get("p") || "index.html";
  const session = getSession(req);

  if (p === "login.html") {
    if (session) return redirect(res, "/");
  } else if (!Object.prototype.hasOwnProperty.call(pages, p)) {
    res.statusCode = 404;
    return res.end("Not found");
  } else if (!session) {
    return redirect(res, "/login");
  }

  res.statusCode = 200;
  res.setHeader("Content-Type", "text/html; charset=utf-8");
  res.setHeader("Cache-Control", "no-store");
  res.end(pages[p]);
};
